public class Main {
    static int square(int x) { //~ A method: it takes an int called x and gives back an int.
        return x * x; //~ return sends the answer back to whoever called square.
    }

    public static void main(String[] args) {
        int a = square(3); //~ Call square with x = 3. main pauses here until square hands back an answer.
        int b = square(a); //~ Call it again, this time with x = 9, the value of a.
        System.out.println(a + " " + b); //~ Print both results.
    }
}

